import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public class Solution {
    static final class Cidr {
        private final int base;
        private final int prefixo;

        private Cidr(int base, int prefixo) {
            this.base = base;
            this.prefixo = prefixo;
        }

        static Cidr parse(String texto) {
            if (texto == null) throw new IllegalArgumentException("bloco nulo");
            int barra = texto.indexOf('/');
            if (barra < 0 || barra != texto.lastIndexOf('/')) throw new IllegalArgumentException("formato esperado: a.b.c.d/p");
            int prefixo = decimal(texto.substring(barra + 1), 32, "prefixo");
            return new Cidr(paraInt(texto.substring(0, barra)) & mascara(prefixo), prefixo);
        }

        /** Converte "a.b.c.d" em int (os 32 bits importam; o sinal não). */
        static int paraInt(String ip) {
            if (ip == null) throw new IllegalArgumentException("ip nulo");
            String[] partes = ip.split("[.]", -1);
            if (partes.length != 4) throw new IllegalArgumentException("esperados 4 octetos: " + ip);
            int v = 0;
            for (String p : partes) v = (v << 8) | decimal(p, 255, "octeto");
            return v;
        }

        private static int decimal(String s, int max, String o) {
            if (s.isEmpty() || s.length() > 3) throw new IllegalArgumentException(o + " inválido: '" + s + "'");
            if (s.length() > 1 && s.charAt(0) == '0') throw new IllegalArgumentException(o + " com zero à esquerda: '" + s + "'");
            int v = 0;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c < '0' || c > '9') throw new IllegalArgumentException(o + " inválido: '" + s + "'");
                v = v * 10 + (c - '0');
            }
            if (v > max) throw new IllegalArgumentException(o + " fora da faixa: " + v);
            return v;
        }

        static String paraTexto(int v) {
            return ((v >>> 24) & 0xff) + "." + ((v >>> 16) & 0xff) + "." + ((v >>> 8) & 0xff) + "." + (v & 0xff);
        }

        /** /0 é especial: em Java, "-1 << 32" é "-1 << 0", ou seja, não zera. */
        static int mascara(int prefixo) {
            return prefixo == 0 ? 0 : -1 << (32 - prefixo);
        }

        int prefixo() {
            return prefixo;
        }

        int baseInt() {
            return base;
        }

        private int ultimo() {
            return base | ~mascara(prefixo);
        }

        String rede() {
            return paraTexto(base);
        }

        String broadcast() {
            return paraTexto(ultimo());
        }

        String primeiroHost() {
            return paraTexto(prefixo >= 31 ? base : base + 1);
        }

        String ultimoHost() {
            return paraTexto(prefixo >= 31 ? ultimo() : ultimo() - 1);
        }

        long totalEnderecos() {
            return 1L << (32 - prefixo);
        }

        long totalHosts() {
            return prefixo >= 31 ? totalEnderecos() : totalEnderecos() - 2;
        }

        boolean contem(String ip) {
            return (paraInt(ip) & mascara(prefixo)) == base;
        }
    }

    static final class TabelaDeRotas {
        // Um mapa por tamanho de prefixo: consulta do /32 ao /0, no máximo 33 acessos.
        @SuppressWarnings("unchecked")
        private final Map<Integer, String>[] porPrefixo = new Map[33];
        private int tamanho;

        TabelaDeRotas() {
            for (int i = 0; i <= 32; i++) porPrefixo[i] = new HashMap<>();
        }

        void adicionar(String cidr, String proximoSalto) {
            if (proximoSalto == null || proximoSalto.isBlank()) throw new IllegalArgumentException("próximo salto vazio");
            Cidr c = Cidr.parse(cidr);
            if (porPrefixo[c.prefixo()].put(c.baseInt(), proximoSalto) == null) tamanho++;
        }

        boolean remover(String cidr) {
            Cidr c = Cidr.parse(cidr);
            boolean havia = porPrefixo[c.prefixo()].remove(c.baseInt()) != null;
            if (havia) tamanho--;
            return havia;
        }

        Optional<String> proximoSalto(String ip) {
            int v = Cidr.paraInt(ip);
            for (int p = 32; p >= 0; p--) {
                Map<Integer, String> mapa = porPrefixo[p];
                if (mapa.isEmpty()) continue;
                String salto = mapa.get(v & Cidr.mascara(p));
                if (salto != null) return Optional.of(salto);
            }
            return Optional.empty();
        }

        int tamanho() {
            return tamanho;
        }
    }
}

