import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.time.Duration;
import java.util.Optional;

class SolutionTest {
    static Solution.Cidr c(String texto) {
        return Solution.Cidr.parse(texto);
    }

    // ---------- Cidr: caso geral ----------

    @Test void redeEBroadcastDeUmSlash24() {
        Solution.Cidr b = c("10.0.2.37/24");
        assertEquals("10.0.2.0", b.rede());
        assertEquals("10.0.2.255", b.broadcast());
        assertEquals(24, b.prefixo());
    }

    @Test void faixaDeHostsDeUmSlash24() {
        Solution.Cidr b = c("10.0.2.0/24");
        assertEquals("10.0.2.1", b.primeiroHost());
        assertEquals("10.0.2.254", b.ultimoHost());
        assertEquals(256, b.totalEnderecos());
        assertEquals(254, b.totalHosts());
    }

    @Test void prefixoQueNaoFechaOcteto() {
        Solution.Cidr b = c("192.168.1.130/25");
        assertEquals("192.168.1.128", b.rede());
        assertEquals("192.168.1.255", b.broadcast());
        assertEquals("192.168.1.129", b.primeiroHost());
        assertEquals("192.168.1.254", b.ultimoHost());
        assertEquals(128, b.totalEnderecos());
        assertEquals(126, b.totalHosts());

        Solution.Cidr d = c("172.16.37.200/27");
        assertEquals("172.16.37.192", d.rede());
        assertEquals("172.16.37.223", d.broadcast());
        assertEquals(30, d.totalHosts());

        Solution.Cidr e = c("10.1.2.3/20");
        assertEquals("10.1.0.0", e.rede());
        assertEquals("10.1.15.255", e.broadcast());
        assertEquals(4094, e.totalHosts());
    }

    @Test void blocosGrandesEPequenos() {
        Solution.Cidr a = c("10.200.3.4/8");
        assertEquals("10.0.0.0", a.rede());
        assertEquals("10.255.255.255", a.broadcast());
        assertEquals(16_777_216L, a.totalEnderecos());
        assertEquals(16_777_214L, a.totalHosts());

        Solution.Cidr b = c("203.0.113.9/30");
        assertEquals("203.0.113.8", b.rede());
        assertEquals("203.0.113.11", b.broadcast());
        assertEquals("203.0.113.9", b.primeiroHost());
        assertEquals("203.0.113.10", b.ultimoHost());
        assertEquals(2, b.totalHosts());
    }

    @Test void enderecosAltosNaoQuebramPorCausaDoSinal() {
        Solution.Cidr b = c("200.100.50.25/26");
        assertEquals("200.100.50.0", b.rede());
        assertEquals("200.100.50.63", b.broadcast());

        Solution.Cidr alto = c("255.255.255.200/25");
        assertEquals("255.255.255.128", alto.rede());
        assertEquals("255.255.255.255", alto.broadcast());
        assertEquals("255.255.255.254", alto.ultimoHost());
    }

    // ---------- Cidr: /31, /32 e /0 ----------

    @Test void slash31NaoReservaRedeNemBroadcast() {
        Solution.Cidr b = c("192.0.2.5/31");
        assertEquals("192.0.2.4", b.rede());
        assertEquals("192.0.2.5", b.broadcast());
        assertEquals("192.0.2.4", b.primeiroHost());
        assertEquals("192.0.2.5", b.ultimoHost());
        assertEquals(2, b.totalEnderecos());
        assertEquals(2, b.totalHosts());
        assertTrue(b.contem("192.0.2.4"));
        assertTrue(b.contem("192.0.2.5"));
        assertFalse(b.contem("192.0.2.6"));
        assertFalse(b.contem("192.0.2.3"));
    }

    @Test void slash32EUmUnicoHost() {
        Solution.Cidr b = c("198.51.100.7/32");
        assertEquals("198.51.100.7", b.rede());
        assertEquals("198.51.100.7", b.broadcast());
        assertEquals("198.51.100.7", b.primeiroHost());
        assertEquals("198.51.100.7", b.ultimoHost());
        assertEquals(1, b.totalEnderecos());
        assertEquals(1, b.totalHosts());
        assertTrue(b.contem("198.51.100.7"));
        assertFalse(b.contem("198.51.100.6"));
        assertFalse(b.contem("198.51.100.8"));
    }

    @Test void slash0CobreTudo() {
        Solution.Cidr b = c("1.2.3.4/0");
        assertEquals("0.0.0.0", b.rede());
        assertEquals("255.255.255.255", b.broadcast());
        assertEquals("0.0.0.1", b.primeiroHost());
        assertEquals("255.255.255.254", b.ultimoHost());
        assertEquals(4_294_967_296L, b.totalEnderecos());
        assertEquals(4_294_967_294L, b.totalHosts());
        assertTrue(b.contem("0.0.0.0"));
        assertTrue(b.contem("198.51.100.7"));
        assertTrue(b.contem("255.255.255.255"));
    }

    // ---------- Cidr: contem ----------

    @Test void contemIncluiRedeEBroadcastEExcluiOsVizinhos() {
        Solution.Cidr b = c("10.0.2.0/24");
        assertTrue(b.contem("10.0.2.0"));
        assertTrue(b.contem("10.0.2.37"));
        assertTrue(b.contem("10.0.2.255"));
        assertFalse(b.contem("10.0.1.255"));
        assertFalse(b.contem("10.0.3.0"));
        assertFalse(b.contem("11.0.2.37"));
    }

    @Test void contemComEnderecosAcimaDe127() {
        assertTrue(c("128.0.0.0/1").contem("255.255.255.255"));
        assertTrue(c("128.0.0.0/1").contem("128.0.0.0"));
        assertFalse(c("128.0.0.0/1").contem("127.255.255.255"));
        assertTrue(c("192.168.0.0/16").contem("192.168.255.1"));
        assertFalse(c("192.168.0.0/16").contem("192.169.0.1"));
    }

    @Test void contemPrefixoQueNaoFechaOcteto() {
        Solution.Cidr b = c("172.16.0.0/12"); // 172.16.0.0 a 172.31.255.255
        assertTrue(b.contem("172.16.0.1"));
        assertTrue(b.contem("172.31.255.254"));
        assertFalse(b.contem("172.32.0.1"));
        assertFalse(b.contem("172.15.255.255"));
    }

    // ---------- Cidr: entradas inválidas ----------

    @Test void blocosInvalidos() {
        String[] ruins = {
            "10.0.0.0", "10.0.0/24", "10.0.0.0.0/24", "10.0.0.256/24", "10.0.0.0/33", "10.0.0.0/-1",
            "a.b.c.d/8", "10.0.0.0/", "/24", "", "10.0.0.0/24/1", " 10.0.0.1/24", "10.0.0.1 /24",
            "+1.0.0.0/8", "010.0.0.0/8", "10.0.0.0/08", "10..0.0/24", "10.0.0.0/2a", "10.0.0.-1/24",
        };
        for (String s : ruins) {
            assertThrows(IllegalArgumentException.class, () -> Solution.Cidr.parse(s), "devia rejeitar: '" + s + "'");
        }
        assertThrows(IllegalArgumentException.class, () -> Solution.Cidr.parse(null));
    }

    @Test void ipInvalidoEmContem() {
        Solution.Cidr b = c("10.0.0.0/8");
        assertThrows(IllegalArgumentException.class, () -> b.contem("10.0.0"));
        assertThrows(IllegalArgumentException.class, () -> b.contem("10.0.0.300"));
        assertThrows(IllegalArgumentException.class, () -> b.contem(null));
    }

    // ---------- TabelaDeRotas ----------

    Solution.TabelaDeRotas tabela() {
        Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
        t.adicionar("0.0.0.0/0", "ISP");
        t.adicionar("10.0.0.0/16", "R2");
        t.adicionar("10.0.5.0/24", "R3");
        return t;
    }

    @Test void escolheOPrefixoMaisLongo() {
        Solution.TabelaDeRotas t = tabela();
        assertEquals(Optional.of("R2"), t.proximoSalto("10.0.9.4"));
        assertEquals(Optional.of("R3"), t.proximoSalto("10.0.5.20"));
        assertEquals(Optional.of("ISP"), t.proximoSalto("198.51.100.7"));
        assertEquals(Optional.of("R2"), t.proximoSalto("10.0.4.255")); // borda: logo antes do /24
        assertEquals(Optional.of("R2"), t.proximoSalto("10.0.6.0"));   // borda: logo depois do /24
        assertEquals(Optional.of("R3"), t.proximoSalto("10.0.5.0"));
        assertEquals(Optional.of("R3"), t.proximoSalto("10.0.5.255"));
    }

    @Test void ordemDeCadastroNaoImporta() {
        Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
        t.adicionar("10.0.5.0/24", "R3");
        t.adicionar("10.0.0.0/16", "R2");
        t.adicionar("0.0.0.0/0", "ISP");
        assertEquals(Optional.of("R3"), t.proximoSalto("10.0.5.20"));
        assertEquals(Optional.of("R2"), t.proximoSalto("10.0.9.4"));
    }

    @Test void semRotaDevolveVazio() {
        Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
        assertEquals(Optional.empty(), t.proximoSalto("10.0.0.1"));
        t.adicionar("10.0.0.0/16", "R2");
        assertEquals(Optional.empty(), t.proximoSalto("198.51.100.7"));
        assertEquals(Optional.of("R2"), t.proximoSalto("10.0.255.255"));
        assertEquals(Optional.empty(), t.proximoSalto("10.1.0.0"));
    }

    @Test void rotaDeHostVenceERotaPadraoCobreTudo() {
        Solution.TabelaDeRotas t = tabela();
        t.adicionar("10.0.5.7/32", "R4");
        assertEquals(Optional.of("R4"), t.proximoSalto("10.0.5.7"));
        assertEquals(Optional.of("R3"), t.proximoSalto("10.0.5.8"));
        assertEquals(Optional.of("ISP"), t.proximoSalto("255.255.255.255"));
        assertEquals(Optional.of("ISP"), t.proximoSalto("0.0.0.0"));
    }

    @Test void rotaSlash31() {
        Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
        t.adicionar("192.0.2.5/31", "link");
        assertEquals(Optional.of("link"), t.proximoSalto("192.0.2.4"));
        assertEquals(Optional.of("link"), t.proximoSalto("192.0.2.5"));
        assertEquals(Optional.empty(), t.proximoSalto("192.0.2.6"));
    }

    @Test void adicionarNormalizaESubstituiOMesmoBloco() {
        Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
        t.adicionar("10.0.5.99/24", "R3");
        assertEquals(1, t.tamanho());
        assertEquals(Optional.of("R3"), t.proximoSalto("10.0.5.1"));
        t.adicionar("10.0.5.0/24", "R9");   // mesmo bloco depois de normalizado
        assertEquals(1, t.tamanho());
        assertEquals(Optional.of("R9"), t.proximoSalto("10.0.5.1"));
    }

    @Test void removerVoltaParaARotaMaisGeral() {
        Solution.TabelaDeRotas t = tabela();
        assertEquals(3, t.tamanho());
        assertTrue(t.remover("10.0.5.0/24"));
        assertEquals(2, t.tamanho());
        assertEquals(Optional.of("R2"), t.proximoSalto("10.0.5.20"));
        assertFalse(t.remover("10.0.5.0/24"));
        assertTrue(t.remover("0.0.0.0/0"));
        assertEquals(Optional.empty(), t.proximoSalto("198.51.100.7"));
    }

    @Test void entradasInvalidasNaTabela() {
        Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
        assertThrows(IllegalArgumentException.class, () -> t.adicionar("10.0.0.0/40", "R1"));
        assertThrows(IllegalArgumentException.class, () -> t.adicionar("10.0.0.0/8", null));
        assertThrows(IllegalArgumentException.class, () -> t.adicionar("10.0.0.0/8", " "));
        assertThrows(IllegalArgumentException.class, () -> t.proximoSalto("10.0.0"));
        assertEquals(0, t.tamanho());
    }

    @Test void consultaNaoVarreATabelaInteira() {
        assertTimeout(Duration.ofSeconds(3), () -> {
            Solution.TabelaDeRotas t = new Solution.TabelaDeRotas();
            t.adicionar("0.0.0.0/0", "padrao");
            for (int a = 0; a < 235; a++) {
                for (int b = 0; b < 256; b++) t.adicionar("10." + a + "." + b + ".0/24", "gw-" + a);
            }
            assertEquals(1 + 235 * 256, t.tamanho());
            int acertos = 0;
            for (int i = 0; i < 200_000; i++) {
                int a = i % 250;
                int b = (i / 250) % 256;
                String salto = t.proximoSalto("10." + a + "." + b + ".77").orElseThrow();
                if (a < 235 ? salto.equals("gw-" + a) : salto.equals("padrao")) acertos++;
            }
            assertEquals(200_000, acertos);
        });
    }
}
